 document.getElementById('quiz-form').addEventListener('submit', function(event) {
     event.preventDefault();

     const answers = {
         q1: ['cpp', 'java', 'haskell'],
         q2: ['cpp', 'python', 'js'],
         q3: ['c', 'rust', 'cpp']
     };

     const resultsDiv = document.getElementById('quiz-results');
     const form = event.target;
     const formData = new FormData(form);

     let score = 0;
     const totalQuestions = Object.keys(answers).length;
     let firstInvalidField = null;
     let hasErrors = false;

     // Reset errors
     document.querySelectorAll('.error-text').forEach(el => el.hidden = true);
     document.querySelectorAll('fieldset').forEach(el => el.removeAttribute('aria-invalid'));

     for (const questionId of Object.keys(answers)) {
         const selectedValues = formData.getAll(questionId);
         const errorEl = document.getElementById(`${questionId}-error`);
         const fieldset = document.getElementById(`${questionId}-fieldset`);

         if (selectedValues.length === 0) {
             hasErrors = true;
             errorEl.hidden = false;
             fieldset.setAttribute('aria-invalid', 'true');
             if (!firstInvalidField) {
                 firstInvalidField = fieldset.querySelector('input');
             }
             continue;
         }

         const correctValues = answers[questionId];
         const isCorrect = 
             selectedValues.length === correctValues.length &&
             selectedValues.every(val => correctValues.includes(val));

         if (isCorrect) {
             score++;
         }
     }

     if (hasErrors) {
         resultsDiv.classList.remove('visible');
         if (firstInvalidField) {
             firstInvalidField.focus();
         }
         return;
     }

     resultsDiv.classList.remove('success', 'error');
     resultsDiv.classList.add('visible');

     if (score === totalQuestions) {
         resultsDiv.classList.add('success');
         resultsDiv.innerHTML = `<strong>Perfect!</strong> You got all ${score} questions right.`;
     } else {
         resultsDiv.classList.add('error');
         resultsDiv.innerHTML = `<strong>Results:</strong> You got ${score} out of ${totalQuestions} correct. Keep learning!`;
     }

     resultsDiv.scrollIntoView({ behavior: 'smooth' });
 });

")
